{
  "name": "Tango命令代理",
  "name_en": "Tango Command Proxy",
  "manufacturer": "",
  "description": "这是一个面向 Tango 控制系统的通用命令与信号代理接口，用于在实验室、光束线或自动化实验装置中连接接入 Tango 的设备，读取当前值与读回值、写入设定或命令，并接收状态更新。根据现有证据，它并不对应单一物理仪器，而是用于操作各类 Tango 受控设备的通用控制组件。",
  "description_en": "This is a generic command and signal proxy interface for the Tango control system, used in laboratories, beamlines, and automated experimental setups to connect to Tango-managed devices, read current and write-back values, send setpoints or commands, and receive updates. Based on the available evidence, it does not represent a single physical instrument but a general control component for interacting with Tango-controlled equipment.",
  "tag_hints": [
    "Tango Controls",
    "distributed instrument control",
    "beamline controls",
    "device command proxy",
    "event subscription",
    "polling readback",
    "attribute and command access"
  ],
  "actions": [
    {
      "action_name": "auto-get",
      "description": "获取当前值或命令返回值。",
      "description_en": "Get the current value or command return value."
    },
    {
      "action_name": "auto-get_w_value",
      "description": "获取写入值或最近一次设定值。",
      "description_en": "Get the written value or most recent set value."
    },
    {
      "action_name": "auto-put",
      "description": "写入一个值或发送带参数的命令。",
      "description_en": "Write a value or send a command with an argument."
    },
    {
      "action_name": "auto-get_config",
      "description": "获取当前信号或命令通道的配置信息。",
      "description_en": "Get configuration information for the current signal or command channel."
    },
    {
      "action_name": "auto-get_reading",
      "description": "获取当前读数及相关读出信息。",
      "description_en": "Get the current reading and associated readout information."
    },
    {
      "action_name": "auto-has_subscription",
      "description": "检查是否已存在更新订阅。",
      "description_en": "Check whether an update subscription is active."
    },
    {
      "action_name": "auto-subscribe_callback",
      "description": "订阅值更新回调。",
      "description_en": "Subscribe a callback for value updates."
    },
    {
      "action_name": "auto-unsubscribe_callback",
      "description": "取消值更新回调订阅。",
      "description_en": "Unsubscribe the value update callback."
    },
    {
      "action_name": "auto-set_polling",
      "description": "设置轮询更新方式与轮询参数。",
      "description_en": "Set the polling update mode and polling parameters."
    },
    {
      "action_name": "auto-set_converter",
      "description": "设置数据转换器。",
      "description_en": "Set the data converter."
    },
    {
      "action_name": "auto-poll",
      "description": "执行一次主动轮询更新。",
      "description_en": "Perform one active polling update."
    },
    {
      "action_name": "auto-datatype_allowed",
      "description": "检查是否支持指定数据类型。",
      "description_en": "Check whether a specified data type is supported."
    },
    {
      "action_name": "auto-set_trl",
      "description": "设置Tango资源定位符（TRL）。",
      "description_en": "Set the Tango resource locator (TRL)."
    },
    {
      "action_name": "auto-source",
      "description": "获取当前数据源标识。",
      "description_en": "Get the current data source identifier."
    },
    {
      "action_name": "auto-get_datakey",
      "description": "获取数据键或数据通道键名。",
      "description_en": "Get the data key or data-channel key name."
    },
    {
      "action_name": "auto-get_value",
      "description": "获取当前值。",
      "description_en": "Get the current value."
    },
    {
      "action_name": "auto-get_setpoint",
      "description": "获取当前设定值。",
      "description_en": "Get the current setpoint."
    },
    {
      "action_name": "auto-set_callback",
      "description": "设置更新回调函数。",
      "description_en": "Set the update callback function."
    },
    {
      "action_name": "auto-allow_events",
      "description": "设置是否允许使用事件更新。",
      "description_en": "Set whether event-based updates are allowed."
    }
  ]
}

